('b3621746-9032-46c1-9e9c-072c55b709a7', '6929aaa9-f3a8-4e28-b959-f6585f65b6b1', '47b0bc29-2ef0-4b57-a3b9-849968031526', 'cab6f8f2-e842-45ee-8b47-75ee8c6a8c73', NULL, 'Designed homepage wireframe in Figma. Excited for the result.', '2025-06-07 18:42:48.757811+00', '2025-06-07 18:42:48.757811+00', NULL),
